#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
vector<int> ys;
vector<int> cnt_;
vector<ll>  cov_;
void update(int node,int lo,int hi,int l,int r,int val){
    if(r<=lo||hi<=l) return;
    if(l<=lo&&hi<=r){ cnt_[node]+=val; }
    else{
        int mid=(lo+hi)/2;
        update(2*node,lo,mid,l,r,val);
        update(2*node+1,mid,hi,l,r,val);
    }
    if(cnt_[node]>0) cov_[node]=(ll)ys[hi]-ys[lo];
    else if(lo+1==hi) cov_[node]=0;
    else cov_[node]=cov_[2*node]+cov_[2*node+1];
}
int main(){
    int n; cin>>n;
    vector<array<int,4>> rects(n);
    for(auto& r:rects) cin>>r[0]>>r[1]>>r[2]>>r[3];
    for(auto& r:rects){ ys.push_back(r[1]); ys.push_back(r[3]); }
    sort(ys.begin(),ys.end()); ys.erase(unique(ys.begin(),ys.end()),ys.end());
    int M=ys.size()-1;
    cnt_.assign(4*M+4,0); cov_.assign(4*M+4,0);
    vector<tuple<int,int,int,int>> events;
    for(auto& r:rects){
        events.push_back({r[0], 1,r[1],r[3]});
        events.push_back({r[2],-1,r[1],r[3]});
    }
    sort(events.begin(),events.end());
    ll area=0; int prev=get<0>(events[0]);
    for(auto& [x,t,y1,y2]:events){
        area+=cov_[1]*(ll)(x-prev);
        int ly=lower_bound(ys.begin(),ys.end(),y1)-ys.begin();
        int ry=lower_bound(ys.begin(),ys.end(),y2)-ys.begin();
        update(1,0,M,ly,ry,t);
        prev=x;
    }
    cout<<area<<"\n";
    return 0;
}

