import java.util.*;
public class Main {
    static int[] cnt; static long[] cov; static int[] ys;
    static void update(int nd,int lo,int hi,int l,int r,int val){
        if(r<=lo||hi<=l)return;
        if(l<=lo&&hi<=r)cnt[nd]+=val;
        else{
            int mid=(lo+hi)/2;
            update(2*nd,lo,mid,l,r,val);
            update(2*nd+1,mid,hi,l,r,val);
        }
        if(cnt[nd]>0)cov[nd]=(long)ys[hi]-ys[lo];
        else if(lo+1==hi)cov[nd]=0;
        else cov[nd]=cov[2*nd]+cov[2*nd+1];
    }
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int[][] rects=new int[n][4];
        TreeSet<Integer> ySet=new TreeSet<>();
        for(int i=0;i<n;i++){for(int j=0;j<4;j++)rects[i][j]=sc.nextInt();ySet.add(rects[i][1]);ySet.add(rects[i][3]);}
        List<Integer> yList=new ArrayList<>(ySet);
        Map<Integer,Integer> yi=new HashMap<>();
        for(int i=0;i<yList.size();i++)yi.put(yList.get(i),i);
        ys=yList.stream().mapToInt(Integer::intValue).toArray();
        int M=ys.length-1;
        cnt=new int[4*M+4];cov=new long[4*M+4];
        int[][] events=new int[2*n][4];
        for(int i=0;i<n;i++){
            events[2*i]  =new int[]{rects[i][0], 1,rects[i][1],rects[i][3]};
            events[2*i+1]=new int[]{rects[i][2],-1,rects[i][1],rects[i][3]};
        }
        Arrays.sort(events,(a,b)->a[0]-b[0]);
        long area=0; int prev=events[0][0];
        for(int[] e:events){
            area+=cov[1]*(long)(e[0]-prev);
            update(1,0,M,yi.get(e[2]),yi.get(e[3]),e[1]);
            prev=e[0];
        }
        System.out.println(area);
    }
}
